import{z as i,x as A,o,c as d,q as t,j as r,D as e,d as l,s,S as n}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"重定位类型","description":"","frontmatter":{"title":"重定位类型","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/relocation-types.md","filePath":"cs/relocation-types.md","lastUpdated":1791413859000}'),B={name:"cs/relocation-types.md"};function c(p,a,T,_,C,h){const E=A("Mermaid");return o(),d("div",null,[a[2]||(a[2]=t('<h1 id="重定位类型" tabindex="-1">重定位类型 <a class="header-anchor" href="#重定位类型" aria-label="Permalink to &quot;重定位类型&quot;">​</a></h1><div class="epigraph"><p>每条重定位记录写明：在这一偏移，用符号的地址按何种公式填多少位。ABS、PC 相对、GOT、TLS 各是一种类型。</p><footer>—— 据 ELF 规范与 psABI（`R_X86_64_*`、`R_RISCV_*`）；主干[链接与重定位](/cs/link-reloc)；Levine 整理</footer></div><p>上一课<a href="/cs/symbol-interposition">符号插入</a> 决定绑到谁。缺口是<strong>怎么写成指令编码</strong>：类型不同，公式 <code>S+A-P</code>、<code>G+A</code> 等不同。主干给过直觉。本课钉类型家族，不枚举全部枚举值。ICF 下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>汇编器对 <code>call foo</code> 发一条对 <code>foo</code> 的 PC 相对重定位。链接或加载时计算位移，检查是否溢出立即数。缺口是<strong>类型 → 公式 → 宽度</strong>，不是预加载序。</p><p>动态：<code>R_*_GLOB_DAT</code>、<code>JUMP_SLOT</code> 填 GOT/PLT。TLS：<code>TPOFF</code> 等，模型不同（GD/IE/LE）。</p><h3 id="类型不是「再编译」" tabindex="-1">类型不是「再编译」 <a class="header-anchor" href="#类型不是「再编译」" aria-label="Permalink to &quot;类型不是「再编译」&quot;">​</a></h3><p>链接器按记录改字节，不调前端。溢出则报 <code>relocation truncated</code>。选择器应选得上的指令，否则后端要改用 GOT 间接。</p><p><span class="marginnote">psABI 文档是权威表。本课家族：绝对、相对、GOT、PLT、TLS。不抄一百行枚举。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译器：PIC 则多发 GOT 型。链接器：静态应用公式；动态把部分记录拷进 <code>rela.dyn</code> 给加载器。检查：对齐、范围。</p>',11)),(o(),r(n,null,{default:e(()=>[s(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22%E5%81%8F%E7%A7%BB%20%2B%20%E7%B1%BB%E5%9E%8B%20%2B%20%E7%AC%A6%E5%8F%B7%20%2B%20addend%22%5D%20--%3E%20F%5B%22%E5%85%AC%E5%BC%8F%22%5D%0A%20%20F%20--%3E%20BYTES%5B%22%E5%86%99%E5%85%A5%E7%BC%96%E7%A0%81%22%5D%0A%20%20F%20--%3E%20FAIL%5B%22%E6%BA%A2%E5%87%BA%E5%88%99%E6%8A%A5%E9%94%99%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>与<a href="/cs/tree-pattern-isel">指令选择</a>：选 <code>b</code> 还是 <code>auipc+jalr</code> 取决于估计范围与 PIC。</p><p><span class="marginnote">术语翻译：重定位类型就是「补数作业的填法说明」——同一道填空题（把这个符号的地址填进去），有的要求填完整地址（ABS），有的只要求填「离我多远」（PC 相对），有的要去查号台翻页再填（GOT 间接）。类型决定公式，公式决定能填几位。</span></p><p><span class="marginnote">数字实例：PC 相对跳转用 32 位中的 21 位编码位移，可达 ±1 MB。目标函数离调用点 2 MB 时，±1 MB 的位移装不下，链接器就报 relocation truncated to fit——不是代码写错，是「距离超出这类填法能表达的半径」，此时要改选带更大立即数的指令序列。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>RELA vs REL：加数在记录里还是在被改处。Relaxation：链接器把远跳改近跳，删序列——RISC-V 常见。不要假设所有类型都可 relax。</p><p>安全：写重定位的段权限，TEXTREL 使文本可写，应避免。</p>',6)),(o(),r(n,null,{default:e(()=>[s(E,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22call%20foo%20%E5%9C%A8%20.text%22%5D%20--%3E%20Q%5B%22%E6%98%AF%E5%90%A6%20PIC%20%2F%20%E8%83%BD%E5%90%A6%E7%9B%B4%E8%BE%BE%22%5D%0A%20%20Q%20--%20%22%E9%9D%9EPIC%2B%E8%8C%83%E5%9B%B4%E5%86%85%22%20--%3E%20B%5B%22PC%E7%9B%B8%E5%AF%B9%3A%20%E5%A1%AB%20S%2BA-P%20%E5%88%B0%E6%8C%87%E4%BB%A4%E9%87%8C%22%5D%0A%20%20Q%20--%20%22PIC%22%20--%3E%20G%5B%22GOT%3A%20%E8%AE%B0%E5%BD%95%E5%A1%AB%E8%BF%9B%E8%A1%A8%2C%20%E6%8C%87%E4%BB%A4%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20B%20--%3E%20T%5B%22%E4%BB%A3%E7%A0%81%E6%AE%B5%E4%BF%9D%E6%8C%81%E5%8F%AA%E8%AF%BB%22%5D%0A%20%20G%20--%3E%20T%0A%20%20B%20--%20%22%E9%9C%80%E8%A6%81%E6%94%B9%E5%86%99%20.text%22%20--%3E%20X%5B%22TEXTREL%3A%20%E6%96%87%E6%9C%AC%E5%8F%AF%E5%86%99%2C%20%E5%BA%94%E9%81%BF%E5%85%8D%22%5D%0A%20%20G%20-.-%3E%20W%5B%22%E7%BB%B4%E6%8A%A4%E6%88%90%E6%9C%AC%E6%8D%A2%E5%AE%89%E5%85%A8%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p>这张图回答的问题是「一次 <code>call foo</code> 最终把地址填到哪里」：填进指令本身，代码段就要被改写（TEXTREL 风险）；改填进 GOT 查询表，代码段永远只读，代价是每次调用多一次内存访问。位置无关代码整体选了后者。</p><p><span class="marginnote">直觉类比：RELA 与 REL 的区别像「答案抄在题卡上」还是「答案抄在卷子空白处」。RELA 把加数放在重定位记录里随身携带；REL 则假定空白处已经预填了加数，补数时读出来再加。现代 RISC-V/x86-64 多用 RELA，因为指令里常没有地方预填。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 TLS 全部模型推导。后课默认：重定位类型由 psABI 定义。下一课 ICF：相同代码节折叠，依赖重定位可调整。</p><p>也不把重定位当 git rebase。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型编码公式与宽度；失败则截断错误。</li><li>PIC/TLS/PLT 使用不同家族。</li><li>relaxation 是链接期再选择。</li><li>出处：ELF 与 psABI；Levine；对照主干 link-reloc。</li></ul>',7))])}const f=i(B,[["render",c]]);export{P as __pageData,f as default};
